import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {TextDecoder, types} from 'node:util';

export function createDecoder(){
  // TextDecoder retains incomplete UTF-8 and ignores exactly one leading BOM.
  const utf8=new TextDecoder('utf-8',{fatal:true});
  let lineParts=[],data=[],event=null;
  let terminated=false,finished=false,failed=false;

  function checkActive(){
    if(failed)throw Error('Decoder has failed');
    if(finished)throw Error('Decoder has finished');
  }

  function acceptLine(line,frames){
    if(line.endsWith('\r'))line=line.slice(0,-1);
    if(terminated){
      if(line!=='')throw Error('Nonblank line after termination');
      return;
    }
    if(line===''){
      if(data.length){
        const value=data.join('\n');
        if(value==='[DONE]')terminated=true;
        else frames.push({event:event||'message',data:value});
      }
      data=[];
      event=null;
      return;
    }
    if(line.startsWith(':'))return;
    const colon=line.indexOf(':');
    const field=colon===-1?line:line.slice(0,colon);
    let value=colon===-1?'':line.slice(colon+1);
    if(value.startsWith(' '))value=value.slice(1);
    if(field==='data')data.push(value);
    else if(field==='event')event=value;
  }

  return {
    push(chunk){
      try{
        checkActive();
        if(!types.isUint8Array(chunk))throw Error('Chunk must be a Uint8Array');
        const text=utf8.decode(chunk,{stream:true}),frames=[];
        let start=0;
        for(let end=text.indexOf('\n');end!==-1;end=text.indexOf('\n',start)){
          lineParts.push(text.slice(start,end));
          acceptLine(lineParts.join(''),frames);
          lineParts=[];
          start=end+1;
        }
        if(start<text.length)lineParts.push(text.slice(start));
        return frames;
      }catch(error){
        failed=true;
        throw error;
      }
    },
    finish(){
      try{
        checkActive();
        const tail=utf8.decode(); // Reject an incomplete final UTF-8 sequence.
        if(tail)lineParts.push(tail);
        if(lineParts.length)throw Error('Unterminated final line');
        if(data.length||event!==null)throw Error('Pending frame fields');
        if(!terminated)throw Error('Missing termination marker');
        finished=true;
        return [];
      }catch(error){
        failed=true;
        throw error;
      }
    },
  };
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  try{
    if(process.argv.length!==3)throw Error('usage: stream-framer.js INPUT_JSON_FILE');
    const input=JSON.parse(new TextDecoder('utf-8',{fatal:true,ignoreBOM:true})
      .decode(fs.readFileSync(process.argv[2])));
    if(input===null||typeof input!=='object'||Array.isArray(input)||!Array.isArray(input.chunks)){
      throw Error('Input must be an object with a chunks array');
    }
    const decoder=createDecoder(),frames=[];
    for(const encoded of input.chunks){
      if(typeof encoded!=='string')throw Error('Base64 chunk must be a string');
      const chunk=Buffer.from(encoded,'base64');
      if(chunk.toString('base64')!==encoded)throw Error('Noncanonical base64 chunk');
      for(const frame of decoder.push(chunk))frames.push(frame);
    }
    decoder.finish();
    process.stdout.write(JSON.stringify({frames})+'\n');
  }catch(error){process.stderr.write(String(error.message)+'\n');process.exitCode=2;}
}

