  const run=(args)=>spawnSync(process.execPath,[cli,...args],{encoding:'utf8'});
  function rejected(result){
    assert.equal(result.status,2);
    assert.equal(result.stdout,'');
    assert.ok(result.stderr.length>0);
  }
  try{
    const chunks=[Buffer.alloc(0),...Array.from(Buffer.from('data: 雪\n\n'+done),byte=>Buffer.from([byte]))];
    fs.writeFileSync(fixture,JSON.stringify({chunks:chunks.map(chunk=>chunk.toString('base64')),extra:true}));
