    rejected(run([]));
    rejected(run([fixture,fixture]));
    rejected(run([path.join(directory,'missing')]));
    rejected(run([directory]));
    const valid=Buffer.from(done).toString('base64');
    const invalid=[null,[],1,'text',{}, {chunks:null},{chunks:{}},{chunks:[]},
      ...[null,1,{},'Zg','Zg=','Zg===','Zh==','Zm9=',' Zg==','Zg==\n','-_=='].map(value=>({chunks:[valid,value]})),
      {chunks:[Buffer.from('data: first\n\n'+done+'bad\n').toString('base64')]}];
    for(const input of invalid){
      fs.writeFileSync(fixture,JSON.stringify(input));
      rejected(run([fixture]));
    }
    fs.writeFileSync(fixture,'{');
    rejected(run([fixture]));
    fs.writeFileSync(fixture,Buffer.concat([Buffer.from('{"chunks":["'+valid+'"],"extra":"'),Buffer.from([0xff]),Buffer.from('"}')]));
    rejected(run([fixture]));
    const imported=spawnSync(process.execPath,['--input-type=module','-e',`import ${JSON.stringify(new URL('../stream-framer.js',import.meta.url).href)}`],{encoding:'utf8'});
    assert.equal(imported.status,0);
    assert.equal(imported.stdout,'');
    assert.equal(imported.stderr,'');
  }finally{
    fs.rmSync(directory,{recursive:true,force:true});
  }
});

